CREATE TABLE "Piece" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "form" TEXT NOT NULL, "clay" TEXT NOT NULL, "glaze" TEXT NOT NULL, "firing" TEXT NOT NULL, "note" TEXT NOT NULL, "price" INTEGER NOT NULL, "color" TEXT NOT NULL);
CREATE TABLE "Commission" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "pieceId" TEXT, "story" TEXT NOT NULL, "month" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Commission_pieceId_fkey" FOREIGN KEY ("pieceId") REFERENCES "Piece"("id") ON DELETE SET NULL ON UPDATE CASCADE);
